          "Adobe’s maternity-photography guide emphasizes preparation, communication with the participant and attention to comfort. The relevant point here concerns production preparation, not personal health judgments derived from timing or pose suggestions.\n\nDiscuss clothing, atmosphere, material the person does not want included and whether other adults participate. Stating a preference is not unprofessional; it can reduce unnecessary shooting and later disagreement.\n\nReturn to those intentions during selection. A pose or expression that felt appropriate on set may communicate differently after a tight crop, another caption or advertising reuse.\n\nKeep only decisions needed for the assignment. The team generally needs the selected image and applicable restrictions, not medical details or unrelated personal information. This lets the right people make decisions without circulating unnecessary information. It also gives the photographer concrete direction: a preferred expression or framing constraint can be acted on, while a vague request to make the subject more relatable leaves both the production and the participant uncertain about what should change."
