          "A participant can use an object naturally, but the photograph alone does not establish comfort, health effects, universal suitability or long-term performance. Separate visible facts from the claim the brand wants to communicate.\n\nFTC’s influencer disclosure guide addresses actual experience and commercial relationships in applicable US contexts. Do not ask someone to discuss experience with an unused product or let an intimate-looking scene conceal the partnership.\n\nConfirm version, color and necessary conditions before checking the caption. An attractive photograph using another sample may need a different selection or explanation; visual quality is not a reason to ignore the difference.\n\nProduct size, position and any detail photograph should follow the task. Packaging need not dominate every image. Brand identification can coexist with the personal story without an inaccurate use being staged merely to make the item more prominent. A useful review note identifies the specific product fact requiring correction, giving the photographer and creator something concrete to resolve together."
