          "Wide, portrait and square exports can come from one photograph without retaining identical meaning. An ordinary object in a wider scene can become the principal endorsement in a close crop, requiring another look at context and wording.\n\nCheck person, action, product and text for the actual placement. An untested fixed safe zone cannot guarantee every screen; inspect the intended display instead.\n\nThe selection photograph illustrates keeping the source image beside its decision record. Retain a few versions with named uses instead of delivering every export and asking the next editor to guess.\n\nIf a crop removes an important condition, reconsider composition or placement. Do not keep shrinking text or put essential explanation only in another post the viewer may never encounter. Each version should accurately complete its own task. A simple export list with file, placement and accepted caption is often enough to make the handoff usable without adding an elaborate management system to a small shoot."
