          "Suppose a creator and brand collaborate on outing preparation, and the photographer delivers a wide portrait, tote detail and setting photograph. Select a set explaining the preparation, then check product version, caption and public-use scope.\n\nAn attractive close-up may suggest a specialized use that has not been confirmed. Exclude it or choose an accurate view of the actual arrangement instead of asking the creator to promise an unsupported effect.\n\nThe creator confirms expression, the brand checks facts, the photographer supplies corresponding exports and the publisher inspects actual display. Leave unfinished items pending rather than describe image selection as publication.\n\nThis hypothetical contains no client result. It shows maternity photography becoming a defined influencer-marketing task: a meaningful story, participant involvement, an actual product role and a version the next owner can accurately receive. The decision record should explain the rejected image as well as the selected one, preventing a later operator from bringing it back simply because it looks attractive outside the context of the original review."
